const getPatientsWithMultipleConditions = `-- name: GetPatientsWithMultipleConditions :many

SELECT 
    pc.patient_id,
    pp.first_name,
    pp.last_name,
    COUNT(*) as condition_count,
    COUNT(*) FILTER (WHERE pc.type = 'chronic') as chronic_count
FROM patient_conditions pc
JOIN patient_profiles pp ON pc.patient_id = pp.id
WHERE pc.status IN ('active', 'managed')
GROUP BY pc.patient_id, pp.first_name, pp.last_name
HAVING COUNT(*) >= $1
ORDER BY condition_count DESC
`

type GetPatientsWithMultipleConditionsRow struct {
	PatientID      pgtype.UUID `json:"patient_id"`
	FirstName      string      `json:"first_name"`
	LastName       string      `json:"last_name"`
	ConditionCount int64       `json:"condition_count"`
	ChronicCount   int64       `json:"chronic_count"`
}

// ============================================
// REPORTING QUERIES
// ============================================
func (q *Queries) GetPatientsWithMultipleConditions(ctx context.Context, dollar_1 interface{}) ([]GetPatientsWithMultipleConditionsRow, error) {
	rows, err := q.db.Query(ctx, getPatientsWithMultipleConditions, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetPatientsWithMultipleConditionsRow{}
	for rows.Next() {
		var i GetPatientsWithMultipleConditionsRow
		if err := rows.Scan(
			&i.PatientID,
			&i.FirstName,
			&i.LastName,
			&i.ConditionCount,
			&i.ChronicCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

