const hasChronicConditions = `-- name: HasChronicConditions :one

SELECT EXISTS(
    SELECT 1 FROM patient_conditions
    WHERE 
        patient_id = $1
        AND type = 'chronic'
        AND status IN ('active', 'managed')
) as has_chronic
`

// ============================================
// VALIDATION & UTILITIES
// ============================================
func (q *Queries) HasChronicConditions(ctx context.Context, patientID pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, hasChronicConditions, patientID)
	var has_chronic bool
	err := row.Scan(&has_chronic)
	return has_chronic, err
}

